// SignupPage signs an email and a password up, then goes on to the links.
export function SignupPage() {
  const auth = useAuth()
  const navigate = useNavigate()
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)

  async function onSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault()
    setBusy(true)
    setError('')
    try {
      const me = await signup(email, password)
      // The session cookie is HttpOnly, so the API decides who is signed in:
      // ask it, and log in with the account just created if it says nobody.
      let who = me
      try {
        who = await getMe()
      } catch {
        who = await login(email, password)
      }
      auth.setMe(who)
      navigate('/links')
    } catch (err) {
      setError(err instanceof ApiError ? err.message : 'could not reach the server')
    } finally {
      setBusy(false)
    }
  }

  return (
    <main>
      <h1>Sign up</h1>
      <form aria-label="Sign up" onSubmit={onSubmit}>
        <label htmlFor="email">Email</label>
        <input id="email" name="email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} required />
        <label htmlFor="password">Password</label>
        <input
          id="password"
          name="password"
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          minLength={10}
          required
        />
        <button type="submit" disabled={busy}>
          Sign up
        </button>
      </form>
      {error !== '' && <p role="alert">{error}</p>}
      <p>
        Already have an account? <Link to="/login">Log in</Link>
      </p>
    </main>
  )
}
