	s.limiters()
	s.mux.HandleFunc("GET /healthz", s.healthz)
	// signup creates an account as the store contract says; the auth card
	// takes it over with bcrypt hashing and the password's own rules.
	s.mux.HandleFunc("POST /api/signup", s.RateLimitAuth(s.signup))
	// The auth card takes these over with its own handlers; they answer
