	}
	if _, ok := links[0]["user_id"]; ok {
		t.Errorf("GET /api/links: the body names a user_id, which no page needs")
	}
	if _, ok := links[0]["target_url"]; !ok {
		t.Errorf("GET /api/links: the body hides the target_url a page copies from")
	}

	if code := doAs(t, srv, http.MethodDelete, "/api/links/theirs-slug", second); code != http.StatusNoContent {
		t.Errorf("DELETE of one's own link: status %d, want 204", code)
	}
	if code := doAs(t, srv, http.MethodDelete, "/api/links/own-slug", second); code != http.StatusNotFound {
		t.Errorf("DELETE of another user's link: status %d, want 404", code)
	}
	if !st.known("own-slug") {
		t.Errorf("the first user's link vanished after a stranger asked for its delete")
	}

	if code := doAs(t, srv, http.MethodDelete, "/api/links/own-slug", first); code != http.StatusNoContent {
		t.Fatalf("DELETE of one's own link: status %d, want 204", code)
	}
	if got := listLinksAs(t, srv, first); len(got) != 0 {
		t.Errorf("GET /api/links after the delete: %v, want none", got)
	}

	if code := doAs(t, srv, http.MethodGet, "/api/links", sessionOf("")); code != http.StatusUnauthorized {
		t.Errorf("GET /api/links without a session: status %d, want 401", code)
	}
}

// clicksOf is the click count the API names for a link, under either of the
// keys it has used: total_clicks of the pages' contract, clicks of the links
// card's.
func clicksOf(link map[string]any) float64 {
	if got, ok := link["total_clicks"].(float64); ok {
		return got
	}
	got, _ := link["clicks"].(float64)
	return got
}

func sessionOf(cookie string) *http.Cookie {
	return &http.Cookie{Name: server.SessionCookie, Value: cookie}
}

func doAs(t *testing.T, srv *httptest.Server, method, path string, cookie *http.Cookie) int {
	t.Helper()
	req, err := http.NewRequest(method, srv.URL+path, bytes.NewReader(nil))
	if err != nil {
		t.Fatal(err)
	}
	req.AddCookie(cookie)
	res, err := srv.Client().Do(req)
	if err != nil {
		t.Fatal(err)
	}
	_, _ = io.Copy(io.Discard, res.Body)
	_ = res.Body.Close()
	return res.StatusCode
}

// listLinksAs reads GET /api/links as the page does: a list of links, whether
// the API wraps it in an object of its own or answers the array directly.
func listLinksAs(t *testing.T, srv *httptest.Server, cookie *http.Cookie) []map[string]any {
	t.Helper()
	req, err := http.NewRequest(http.MethodGet, srv.URL+"/api/links", nil)
	if err != nil {
		t.Fatal(err)
	}
	req.AddCookie(cookie)
	res, err := srv.Client().Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = res.Body.Close() }()
	if res.StatusCode != http.StatusOK {
		t.Fatalf("GET /api/links: status %d, want 200", res.StatusCode)
	}
	var raw any
	if err := json.NewDecoder(res.Body).Decode(&raw); err != nil {
		t.Fatalf("GET /api/links: body is not JSON: %v", err)
	}
	switch v := raw.(type) {
	case []any:
		return mapsOf(v)
	case map[string]any:
		return mapsOf(v["links"])
	}
	t.Fatalf("GET /api/links: body %v, want the caller's links", raw)
	return nil
}

func mapsOf(v any) []map[string]any {
	list, _ := v.([]any)
	out := make([]map[string]any, 0, len(list))
	for _, item := range list {
		if m, ok := item.(map[string]any); ok {
			out = append(out, m)
		}
	}
	return out
}

// pageLinkStore is the store contract as the my links page sees it: two users
